#!/usr/bin/env python3
"""Turn 35 Wave 47: PRIZE LADDER & DREAM POINTS ECONOMICS - the official DP boost rules and their exclusions, the per-match DP breakdown, milestone structure (50k/62.5k/70k/200k), matches needed (300-324 first / 1370-1428 all four / 15 per day / 137 hours), DLL vs Career DP efficiency, Italian League Classics, filler-reward criticism, the C-020 resolution toward ~2,000 gems, DLL Quests and event rewards."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w47')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-452: official prize ladder ----------
e_pl=new_ev("FTG support 23108987826962 'What is the Prize Ladder?', FTG support 24081168829330 'What are Dream Point Boosts?', Bluestacks DLS26 free-rewards guide, official FTG TikTok (Italian League Classics)",
    "OFFICIAL PRIZE LADDER AND DP BOOST RULES. THE PRIZE LADDER (FTG): 'similarly to the Season Pass, awards items based on your progression. The items can include - coins, gems, coaches, dream point boosts, special players and more! Dream Points are given in matches and the more you earn, the more rewards you will unlock.' The DP BOOST rules are the operationally important part: boosts 'temporarily increase the number of Dream Points that you are awarded during your matches', and they apply ONLY to CAREER MATCHES, DREAM DRAFT MATCHES, SCENARIO MATCHES AND DLL (MULTIPLAYER) MATCHES. THEY DO NOT APPLY TO EXHIBITION AND FRIEND MATCHES. Two further official rules matter for planning: boosts CANNOT be used if the Prize Ladder is complete or no longer active, and ANY UNUSED DREAM POINT BOOSTS REMAIN IN YOUR INVENTORY FOR THE NEXT PRIZE LADDER - so buying boosts late in a dying ladder wastes them, while buying them early carries them forward. The ladder is a PASSIVE system: it runs in the background as you play normally and requires no specific action beyond playing matches, but rewards must be claimed as each tier is hit or they go uncollected during the 90-day window. OFFICIAL CONFIRMATION OF A NEW CLASSIC SET: the official TikTok announces ITALIAN LEAGUE CLASSICS for DLS26 - Trezeguet, Batistuta, Crespo and Desailly - as special Classic Player cards earned by playing matches to accumulate Dream Points. PROGRESSION BANK (official via Bluestacks): it accumulates coins and gems based on your Dream League Live XP earned during a 10-day season, and the full amount is paid out when the season ends.",
    "evidence/raw/turn35_w47/EV-452_prize_ladder_official.html",
    "OFFICIAL PRIZE LADDER: like the Season Pass, awards items on progression - coins, gems, coaches, dream point boosts, special players and more. OFFICIAL DP BOOST RULES: boosts apply ONLY to career matches, dream draft matches, scenario matches and DLL (multiplayer) matches. THEY DO NOT APPLY TO EXHIBITION AND FRIEND MATCHES. Boosts CANNOT be used if the Prize Ladder is complete or inactive, and UNUSED BOOSTS CARRY OVER to the next Prize Ladder - so buying boosts late in a dying ladder wastes them, buying early banks them. The ladder is PASSIVE: it runs in the background as you play, but rewards must be claimed as each tier is hit. OFFICIAL NEW CLASSIC SET: Italian League Classics - Trezeguet, Batistuta, Crespo, Desailly. PROGRESSION BANK: accumulates coins and gems from DLL XP over a 10-day season, paid out in full at season end",
    quality="official")

add_claim("OFFICIAL: Dream Point Boosts apply ONLY to career matches, dream draft matches, scenario matches and DLL (multiplayer) matches. They do NOT apply to exhibition and friend matches.", 1, "economy/dp-boost-exclusions", [e_pl], notes="Exhibition is a free practice ground but earns no boosted DP")
add_claim("OFFICIAL: unused Dream Point Boosts remain in your inventory for the next Prize Ladder, and boosts cannot be used if the Prize Ladder is complete or no longer active.", 1, "economy/dp-boost-carryover", [e_pl], notes="Buy boosts early in a ladder, never late in a dying one")
add_claim("OFFICIAL: the Prize Ladder is a passive system that runs in the background as you play - no specific action is needed beyond playing matches - but rewards must be claimed as each tier is hit or they go uncollected during the 90-day window.", 1, "economy/prize-ladder-passive", [e_pl])
add_claim("OFFICIAL: the Prize Ladder awards coins, gems, coaches, dream point boosts, special players and more, and each cycle lasts 90 days before resetting with fresh rewards and new Classic Players.", 1, "economy/prize-ladder-contents", [e_pl])
add_claim("OFFICIAL: Italian League Classics are coming to DLS26 - Trezeguet, Batistuta, Crespo and Desailly as special Classic Player cards, earned by accumulating Dream Points.", 1, "cards/italian-league-classics", [e_pl])
add_claim("OFFICIAL: the Progression Bank accumulates coins and gems based on your Dream League Live XP earned during a 10-day season, and the full amount is paid out when the season ends.", 1, "economy/progression-bank-confirmed", [e_pl])

# ---------- EV-453: DP economics ----------
e_dp=new_ev("r/DreamLeagueSoccer 1q9vheb (Jan 11 2026, per-match DP breakdown), 1h76l31 (Dec 5 2024, matches to unlock all four), 1h6qiyy (Dec 4 2024, 15 games/day), 1inn7ko (prize ladder grind), 1i4lpm0 (Jan 19 2025, 70k milestone), 1omk8oi (Nov 2 2025, completed ladder), 1ha876r (Dec 9 2024, filler rewards), 1pp07c2 (Dec 17 2025, special coaches), 1v2wldt (Jul 21 2026, World Cup Winners cost), 1d3ludc (May 29 2024, event rewards), r/DLS monthly clan thread (DLL Quests), gamingonphone DP guide, kitdls, sportysure",
    "DREAM POINT ECONOMICS IN DETAIL. THE PER-MATCH DP BREAKDOWN: 115 DP for a Dream League Live win, 65 DP for a Career win, 10 DP per goal up to 5 goals (50 DP maximum), and a clean-sheet bonus reported as either 10 or 15 DP depending on source. On top of the match itself, watching the post-match ad pays a further 50 DP for a DLL win and 35 DP for a Career win. Non-win results also pay: 45 DP for a DLL draw, 15 DP for a DLL loss, and 25 DP from the ad on either. THE EFFICIENCY CONSEQUENCE: a DLL win pays roughly 115 DP against a Career win's 65 DP, so DLL is about 77% more DP-efficient per match for the same effort - which is why experienced players report completing the Prize Ladder playing 'DLL only, and few career matches to complete the daily challenges'. DP BOOST PRICING: a Common boost at 50% for 25 gems covering 3 matches, a Rare boost at 75% for 35 gems covering 5 matches, and a Legendary boost at 150% for 125 gems covering 8 matches. One source reports the boost tiers as 50/70/150 rather than 50/75/150 - a minor unresolved variance. THE MATHS OF THE LADDER: the first special player arrives at roughly 50,000 DP and is RANDOM, drawn like a Legendary Agent; further milestones sit at 62,500 and 70,000 DP (one player reports claiming a special player at 70,000 alongside a 75% boost), and all four specials require about 200,000 DP. In match terms: 300-305 games for the first icon using the free available boosters, 324 games with boosters factored in, and 1,370-1,428 games for all four. At a Career maximum of 140 DP per match, 200,000 DP is 1,428 games. The community's headline calculation is that you need AT LEAST 15 games a day to reach 200,000 DP in the 90-day window - which one poster notes is 'like 60% of a career season' and equates to 54 career seasons in 90 days. Total time cost for all four icons is reported at 1,370 matches x 6 minutes = 8,220 minutes = 137 HOURS. One pragmatic counterpoint: at 3.6 matches per day you get one special player, which some players consider worth it purely for nostalgia while others judge the whole ladder 'not useful for old players'. THE FILLER-REWARD CRITICISM is worth taking seriously: the coin and gem rewards are described as 'very mediocre, unfulfilling, boring and quite frankly useless - they are FILLER rewards', with one player reporting that redeeming Legendary Scouts from the ladder did not even find a Legendary player. A COMPLETED LADDER report lists the draw order as Souness, Adams, Andy Cole, Gascoigne - confirming that the special-player order within a ladder is random. THE C-020 RESOLUTION: a World Cup Winners thread states plainly that 'each special player costs around 2000 gems to max out', which independently corroborates the coach-model estimate of 2,100 gems and resolves the conflict in favour of roughly 2,000-2,100 gems. A related special-coach thread puts the requirement at 6-7 Legendary Special Coaches per maxed special player and calculates a 420-gem saving from the cancel-without-consumption technique, which is consistent with the Legendary Scout trick already in the KB. DLL QUESTS: located in the Quest area, they pay gems for DLL win counts - 5 gems for 5 DLL wins and 175 gems for 175 DLL wins. DLL EVENT REWARDS: winning 5 games in a DLL event pays 280 coins, and winning 7 pays a further 720 on top.",
    "evidence/raw/turn35_w47/EV-453_dp_economics.html",
    "PER-MATCH DP: 115 for a DLL win, 65 for a Career win, 10 per goal up to 5 (50 max), clean sheet 10 or 15 DP (source variance). Post-match ads add 50 DP for a DLL win and 35 for a Career win. Non-wins also pay: 45 DP DLL draw, 15 DP DLL loss, 25 DP from the ad on either. EFFICIENCY: DLL pays ~77% more DP per match than Career, which is why experienced players complete the ladder playing 'DLL only'. BOOST PRICING: Common 50% for 25 gems (3 matches), Rare 75% for 35 gems (5 matches), Legendary 150% for 125 gems (8 matches); one source says 50/70/150. LADDER MATHS: first special at ~50,000 DP and RANDOM; further milestones at 62,500 and 70,000 DP; all four specials ~200,000 DP. Matches: 300-305 for the first icon with free boosters, 324 with boosters, 1,370-1,428 for all four; at the 140 DP career max that is 1,428 games. HEADLINE: you need AT LEAST 15 games a day for 200,000 DP in 90 days - '60% of a career season', 54 career seasons in 90 days. Total time for all four: 1,370 x 6 min = 8,220 min = 137 HOURS. Counterpoint: 3.6 matches/day gets one special, worth it for nostalgia only per some. FILLER REWARDS: coins/gems described as mediocre and useless, with one player's Legendary Scouts from the ladder finding no Legendary. COMPLETED LADDER draw order: Souness, Adams, Andy Cole, Gascoigne - confirming the order is random. C-020 RESOLVED: 'each special player costs around 2000 gems to max out' corroborates the 2,100-gem coach-model estimate. SPECIAL COACHES: 6-7 Legendary Special Coaches per maxed special player, with a 420-gem saving from cancel-without-consumption. DLL QUESTS: 5 gems for 5 DLL wins, 175 gems for 175 DLL wins. DLL EVENTS: 5 wins = 280 coins, 7 wins = +720 more",
    quality="community")

add_claim("Per-match Dream Points: 115 for a DLL win, 65 for a Career win, 10 per goal up to 5 goals (50 max), and a clean-sheet bonus reported as 10 or 15 DP depending on source.", 3, "economy/dp-per-match-breakdown", [e_dp], notes="Clean-sheet value conflicts: 10 vs 15")
add_claim("Post-match ads add a further 50 DP for a DLL win and 35 DP for a Career win; non-win results still pay - 45 DP for a DLL draw, 15 DP for a DLL loss, and 25 DP from the ad on either.", 3, "economy/dp-ad-and-nonwin", [e_dp])
add_claim("A DLL win pays about 115 DP against a Career win's 65 DP, making DLL roughly 77% more DP-efficient per match - which is why experienced players complete the Prize Ladder playing DLL only with a few Career matches for daily challenges.", 3, "economy/dll-more-dp-efficient", [e_dp])
add_claim("DP boost pricing: Common 50% for 25 gems covering 3 matches, Rare 75% for 35 gems covering 5 matches, Legendary 150% for 125 gems covering 8 matches. One source reports the tiers as 50/70/150 rather than 50/75/150.", 3, "economy/dp-boost-pricing", [e_dp], notes="Minor unresolved variance on the Rare tier")
add_claim("Prize Ladder milestones: the first special player arrives at roughly 50,000 DP and is RANDOM, drawn like a Legendary Agent; further milestones sit at 62,500 and 70,000 DP; all four specials require about 200,000 DP.", 3, "economy/prize-ladder-milestones", [e_dp])
add_claim("Matches required: 300-305 games for the first icon using free boosters, 324 games with boosters factored in, and 1,370-1,428 games for all four specials - at the 140 DP career maximum, 200,000 DP is 1,428 games.", 3, "economy/prize-ladder-matches-required", [e_dp])
add_claim("You need AT LEAST 15 games a day to reach 200,000 DP within the 90-day Prize Ladder window - described as '60% of a career season' and equivalent to 54 career seasons in 90 days. Total time for all four icons is about 137 hours.", 3, "economy/prize-ladder-daily-load", [e_dp], notes="The single most important feasibility number for the ladder")
add_claim("A completed Prize Ladder report lists the draw order as Souness, Adams, Andy Cole then Gascoigne, confirming that the special-player order within a ladder is random rather than fixed.", 3, "economy/ladder-draw-order-random", [e_dp])
add_claim("FILLER-REWARD CRITICISM: the Prize Ladder's coin and gem rewards are described as 'very mediocre, unfulfilling, boring and quite frankly useless - they are FILLER rewards', with one player reporting that redeeming Legendary Scouts from the ladder did not even find a Legendary player.", 3, "economy/prize-ladder-filler-criticism", [e_dp])
add_claim("C-020 RESOLVED TOWARD 2,000-2,100 GEMS: a World Cup Winners thread states plainly that 'each special player costs around 2000 gems to max out', independently corroborating the coach-model estimate of 2,100 gems. A related thread puts the requirement at 6-7 Legendary Special Coaches per maxed special player.", 3, "economy/special-player-max-cost-resolved", [e_dp], notes="Closes C-020")
add_claim("The cancel-without-consumption special-coach technique is calculated to save about 70 gems per coach, or roughly 420 gems per maxed special player across 6-7 coaches.", 3, "economy/special-coach-cancel-saving", [e_dp], notes="Corroborates the Legendary Scout trick")
add_claim("DLL Quests, located in the Quest area, pay gems for DLL win counts - 5 gems for 5 DLL wins and 175 gems for 175 DLL wins.", 3, "dll/quests-gem-milestones", [e_dp])
add_claim("DLL event rewards: winning 5 games in a DLL event pays 280 coins, and winning 7 games pays a further 720 coins on top.", 3, "dll/event-rewards", [e_dp])

p=os.path.join(RAW_DIR,'EV-452_prize_ladder_official.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
p2=os.path.join(RAW_DIR,'EV-453_dp_economics.html')
if not os.path.exists(p2):
    with open(p2,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
